function flattenObject(obj) {
  var result = {};

  if (obj === null || typeof obj !== "object" || Array.isArray(obj)) {
    return result;
  }

  var stack = [{ value: obj, prefix: "" }];

  while (stack.length > 0) {
    var frame = stack.pop();
    var value = frame.value;
    var prefix = frame.prefix;

    for (var key in value) {
      if (!Object.prototype.hasOwnProperty.call(value, key)) {
        continue;
      }

      var fullKey = prefix ? prefix + "." + key : key;
      var child = value[key];
      var proto = child === null ? null : Object.getPrototypeOf(child);
      var isPlainObject =
        child !== null &&
        typeof child === "object" &&
        !Array.isArray(child) &&
        (proto === Object.prototype || proto === null);

      if (isPlainObject) {
        stack.push({ value: child, prefix: fullKey });
      } else {
        result[fullKey] = child;
      }
    }
  }

  return result;
}
